// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        address recipient = address(0xdead);
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 2 ether}("");
        require(success, "deposit failed");
        vm.prank(address(this));
        c.withdrawAll(recipient);
        assertTrue(address(c).balance == 0 ether);
    }
}
